// La orden llega por su propio subject (papid.envasadora.orden.<code>) que
// publica el dashboard de envasadoras. Guardamos SOLO la bandera; el cambio de
// pantalla lo decide 'function 1' cuando llega personal del emitter.
let d = msg.payload;
if (typeof d === 'string') { try { d = JSON.parse(d); } catch (e) { return null; } }
if (!d || typeof d.tiene_orden !== 'boolean') return null;

flow.set('orden_ok', d.tiene_orden);
node.status({ fill: d.tiene_orden ? 'green' : 'grey', shape: 'dot', text: d.tiene_orden ? 'con orden' : 'sin orden' });
return null;

// ============================================================
// Cambio de pantalla (envasadoras) - adaptado de las a2i.
// Recibe papid.emitter.<code> (personal + status del emitter).
// La ORDEN viene aparte, en flow.orden_ok (subject de orden del dashboard).
//
// Salta a Envasadoras con PERSONAL TODO ACTIVO + ORDEN.
// Si falta cualquiera (sin personal, alguien en 'Asignado', o sin orden)
// regresa a Dashboard Personal.
// ============================================================

// AJUSTA estos títulos por silo (coincidir con el <title> real; wmctrl -l).
const PANTALLA_ENVASADORAS = 2;
const NOMBRE_ENVASADORAS   = '"Envasadoras | COTIJA | B2-A Silo 1"';
const PANTALLA_PERSONAL    = 1;
const NOMBRE_PERSONAL      = '"Dashboard Personal"';

let datos = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
if (!datos || !Array.isArray(datos.personnel)) {
    return null;
}

const personal = datos.personnel;
const hayOrden = flow.get('orden_ok') === true;

function estadoDe(p) {
    return (p && typeof p.status === 'string') ? p.status.trim() : '';
}

const todosRegistrados = personal.every(function (p) {
    const s = estadoDe(p);
    return s === 'Activo' || s === 'Inactivo';
});
const todosActivos = personal.every(function (p) {
    return estadoDe(p) === 'Activo';
});

const pantalla = Number(flow.get('pantallaActual'));
const enDashboardPersonal = pantalla === PANTALLA_PERSONAL;
const cambioHecho = flow.get('cambioHecho') === true;
const listo = todosRegistrados && hayOrden;

function irAPersonal() {
    flow.set('pantallaActual', PANTALLA_PERSONAL);
    msg.payload = NOMBRE_PERSONAL;
    return msg;
}

// Sin personal, o personal incompleto (alguien en 'Asignado'), o sin orden:
// de vuelta a Dashboard Personal (y rearmamos el cambio).
if (personal.length === 0 || !listo) {
    flow.set('cambioHecho', false);
    return enDashboardPersonal ? null : irAPersonal();
}

// Candado abierto: todos registrados Y orden presente. El salto automático
// solo ocurre cuando TODOS están Activos (ya pasaron la tarjeta), una sola vez.
if (todosActivos && !cambioHecho) {
    flow.set('cambioHecho', true);
    flow.set('pantallaActual', PANTALLA_ENVASADORAS);
    msg.payload = NOMBRE_ENVASADORAS;
    return msg;
}

return null;

let fecha = new Date().toLocaleString('es-MX');
let pantalla = String(msg.payload).replace(/"/g, '');
msg.payload = fecha + ' | Cambio a: ' + pantalla + '\n';
return msg;

// Arranque de la NUC: mostramos Dashboard Personal y dejamos las banderas en
// el estado inicial. El cambio automático se rearma.
flow.set('pantallaActual', 1); // Dashboard Personal
flow.set('cambioHecho', false);
if (flow.get('orden_ok') === undefined) {
    flow.set('orden_ok', false);
}
node.warn('Arranque pantalla: ' + (msg.payload && msg.payload.pantalla_id));
msg.payload = '"Dashboard Personal"';
return msg;

// Inicializa banderas al arrancar/desplegar Node-RED, por si llega un mensaje
// del emitter antes del POST /pantalla-listo.
if (flow.get('pantallaActual') === undefined) flow.set('pantallaActual', 1);
if (flow.get('cambioHecho') === undefined) flow.set('cambioHecho', false);
if (flow.get('orden_ok') === undefined) flow.set('orden_ok', false);
return null;
